54	/** Replays an input log: each entry becomes that ship's held input from its frame on. */
55	function run(initial: MatchState, log: readonly LoggedInput[], steps: number, stepConfig: SimulationConfig = config): MatchState {
56	  let state = initial;
57	  const held: Record<string, PlayerInput> = {};
58	  for (let index = 0; index < steps; index++) {
59	    const frame = state.frame + 1;
60	    for (const entry of log) if (entry.frame === frame) held[entry.shipId] = entry.input;
61	    state = step(stepConfig, state, held);
62	  }
63	  return state;
64	}
