190:    expect(clearCourse(centre(hostTile.tileX, row), centre(away.tileX, row))).toBe(true);
191:    await place(request, host, code, hostTile.tileX, row, compassHeading("E"));
192:    await place(request, guest, code, guestTile.tileX, row, compassHeading("W"));
198:    expect(guestStart.x - hostShip.x).toBeGreaterThanOrEqual(12 * TILE);
199:    expect(guestStart.x - hostShip.x).toBeLessThanOrEqual(13 * TILE);
233:    await sailTo(guest, centre(away.tileX, away.tileY), { until: async () => !(await listedIds(guest)).includes(hostId) });

