1	import { describe, expect, it } from "vitest";
2	import tiledSource from "../../../assets/source/maps/slice-sea.tmj?raw";
3	import { sliceSeaTmj } from "../../../assets/source/maps/sliceSeaSketch.js";
4	import generatedModule from "./maps/sliceSea.ts?raw";
5	import { sliceSeaSource } from "./maps/sliceSea.js";
6	import { privateMatch, rulesPresets } from "./rules.js";
7	import { ENGAGEMENT_RANGE_TILES, shipTuning, SIGHT_RADIUS_TILES, travelTargets } from "./sailing.js";
8	import { seaMap, spawnSlots } from "./sea.js";
9	import { createSeaMap, dockLabel, insideIsland, Terrain, terrainAt, type SeaMapSource } from "./seaMap.js";
10	import { inHubDisc, MAX_SEA_SIDE_TILES, obstacleDistancesSquared, octileStepCosts, seaPathCosts, validateSeaMap, type SeaMapReport } from "./seaValidation.js";
11	import { convertTiledMap, formatSeaMapModule, type TiledMap } from "./tiledMap.js";
12	
13	const SOURCE_PATH = "assets/source/maps/slice-sea.tmj";
14	
15	describe("map pipeline", () => {
16	  it("keeps the generated module in step with the Tiled source map (run `npm run map:build` after editing it)", () => {
17	    const converted = convertTiledMap("slice-sea", JSON.parse(tiledSource));
18	    if (!converted.ok) throw new Error(converted.issues.join("\n"));
19	    expect(converted.value).toEqual(sliceSeaSource);
20	    expect(formatSeaMapModule(converted.value, "sliceSeaSource", SOURCE_PATH)).toBe(generatedModule);
21	  });
22	
23	  it("keeps the Tiled source map in step with the sketch it is drawn from (run `node assets/source/maps/sketch.ts`)", () => {
24	    expect(sliceSeaTmj()).toBe(tiledSource);
25	  });
26	
27	  const tiled = (): TiledMap => JSON.parse(tiledSource) as TiledMap;
28	  const issuesOf = (candidate: unknown) => {
29	    const result = convertTiledMap("broken", candidate);
30	    return result.ok ? [] : result.issues;
31	  };
32	
33	  it("refuses maps outside the documented Tiled subset", () => {
34	    const infinite = { ...tiled(), infinite: true };
35	    const extraLayer = { ...tiled(), layers: [...tiled().layers, { type: "imagelayer", name: "art" }] };
36	    const bigTiles = { ...tiled(), tilewidth: 32 };
37	    for (const broken of [infinite, extraLayer, bigTiles, "not a map"]) expect(issuesOf(broken).length).toBeGreaterThan(0);
38	  });
39	
40	  it("refuses an empty cell, a tile without a terrain type, and flipped tiles", () => {
41	    for (const gid of [0, 9, 0x80000002]) {
42	      const map = tiled();
43	      map.layers[0].data[5] = gid;
44	      expect(issuesOf(map).length).toBeGreaterThan(0);
45	    }
46	  });
47	
48	  it("refuses badly authored objects", () => {
49	    const edit = (change: (objects: TiledMap["layers"][1]["objects"]) => void) => {
50	      const map = tiled();
51	      change(map.layers[1].objects);
52	      return issuesOf(map);
53	    };
54	    const island = (objects: TiledMap["layers"][1]["objects"]) => objects.find((object) => object.type === "island")!;
55	    const spawn = (objects: TiledMap["layers"][1]["objects"]) => objects.find((object) => object.type === "spawn")!;
56	    expect(edit((objects) => void (island(objects).x += 3))).toEqual([expect.stringMatching(/tile boundaries/)]);
57	    expect(edit((objects) => void (island(objects).properties = [{ name: "theme", type: "string", value: "candy" }]))).toEqual([
58	      expect.stringMatching(/theme must be one of/),
59	    ]);
60	    expect(edit((objects) => void spawn(objects).properties!.push({ name: "loot", type: "int", value: 3 }))).toEqual([
61	      expect.stringMatching(/unknown property "loot"/),
62	    ]);
63	    expect(edit((objects) => void (spawn(objects).properties = [{ name: "slot", type: "int", value: 0 }]))).toEqual([
64	      expect.stringMatching(/facing must be one of/),
65	    ]);
66	    const repeated = edit((objects) => void spawn(objects).properties!.forEach((entry) => entry.name === "slot" && (entry.value = 5)));
67	    expect(repeated).toEqual(["spawns: slots must run 0, 1, 2… without gaps or repeats (found 1, 2, 3, 4, 5, 5, 6, 7)"]);
68	  });
69	
70	  it("reads exactly one hub point", () => {
71	    const edit = (change: (objects: TiledMap["layers"][1]["objects"]) => void) => {
72	      const map = tiled();
73	      change(map.layers[1].objects);
74	      return issuesOf(map);
75	    };
76	    const hubIndex = (objects: TiledMap["layers"][1]["objects"]) => objects.findIndex((object) => object.type === "hub");
77	    expect(edit((objects) => void objects.splice(hubIndex(objects), 1))).toEqual(["objects: 0 hub points, not one"]);
78	    expect(edit((objects) => void objects.push({ ...objects[hubIndex(objects)]!, id: 99 }))).toEqual(["objects: 2 hub points, not one"]);
79	    expect(edit((objects) => void (objects[hubIndex(objects)]!.point = false))).toEqual([expect.stringMatching(/a hub is a point/)]);
80	    expect(edit((objects) => void (objects[hubIndex(objects)]!.properties = [{ name: "slot", type: "int", value: 0 }]))).toEqual([
81	      expect.stringMatching(/unknown property "slot"/),
82	    ]);
83	  });
84	});
85	
86	/** The slice map with some tiles changed: `edits` maps "x,y" to a terrain character. */
87	function editedMap(edits: Record<string, string>, change: Partial<SeaMapSource> = {}): SeaMapSource {
88	  const rows = sliceSeaSource.rows.map((row, tileY) =>
89	    [...row].map((char, tileX) => edits[`${tileX},${tileY}`] ?? char).join(""),
90	  );
91	  return { ...sliceSeaSource, rows, ...change };
92	}
93	
94	function issuesFor(source: SeaMapSource, tuning = shipTuning): string[] {
95	  const result = validateSeaMap(createSeaMap(source), tuning);
96	  return result.ok ? [] : result.issues;
97	}
98	
99	function sliceReport(): SeaMapReport {
100	  const result = validateSeaMap(seaMap, shipTuning);
101	  if (!result.ok) throw new Error(result.issues.join("\n"));
102	  return result.value;
103	}
104	
105	/** Every tile of a rectangle, as edits. */
106	function fill(tileX: number, tileY: number, width: number, height: number, char: string): Record<string, string> {
107	  const edits: Record<string, string> = {};
108	  for (let y = tileY; y < tileY + height; y++) for (let x = tileX; x < tileX + width; x++) edits[`${x},${y}`] = char;
109	  return edits;
110	}
111	
112	describe("the slice sea", () => {
113	  it("passes every map validator", () => {
114	    const result = validateSeaMap(seaMap, shipTuning);
115	    if (!result.ok) throw new Error(result.issues.join("\n"));
116	  });
117	
118	  it("has four small islands, each with a dock beside its land, shoals, and eight outer-sea spawn slots", () => {
119	    expect(seaMap.islands).toHaveLength(rulesPresets.slice.islands);
120	    expect(seaMap.islands).toHaveLength(4);
121	    seaMap.islands.forEach((island, index) => {
122	      expect(seaMap.docks.filter((dock) => dock.island === index).length).toBeGreaterThanOrEqual(1);
123	      expect(island.widthTiles * island.heightTiles).toBeLessThanOrEqual(16 * 16);
124	    });
125	    expect(seaMap.terrain.filter((kind) => kind === Terrain.Shoal).length).toBeGreaterThan(0);
126	    expect(spawnSlots).toHaveLength(privateMatch.maxPlayers);
127	    expect(new Set(spawnSlots.map((slot) => `${slot.tileX},${slot.tileY}`)).size).toBe(8);
128	    for (const slot of spawnSlots) {
129	      expect(terrainAt(seaMap, slot.tileX, slot.tileY)).toBe(Terrain.Sea);
130	      expect(seaMap.islands.some((island) => insideIsland(island, slot.tileX, slot.tileY))).toBe(false);
131	    }
132	    expect(dockLabel(seaMap, 0)).toMatch(/^[A-Z][a-z]+ [A-Z][a-z]+, [a-z-]+ dock$/);
133	  });
134	
135	  it("meets the travel-time targets at full speed", () => {
136	    const result = validateSeaMap(seaMap, shipTuning);
137	    if (!result.ok) throw new Error(result.issues.join("\n"));
138	    const { nearestIsland, longestCrossing, firstDock } = result.value;
139	    expect(nearestIsland).toHaveLength(4);
140	    for (const entry of nearestIsland) {
141	      expect(entry.seconds).toBeGreaterThanOrEqual(20);
142	      expect(entry.seconds).toBeLessThanOrEqual(40);
143	    }
144	    expect(longestCrossing.seconds).toBeLessThanOrEqual(90);
145	    for (const entry of firstDock) expect(entry.seconds).toBeLessThanOrEqual(travelTargets.firstDockMaxSeconds);
146	  });
147	
148	  it("starts adjacent spawn slots out of engagement range, and sees further than it engages", () => {
149	    expect(SIGHT_RADIUS_TILES).toBeGreaterThan(ENGAGEMENT_RANGE_TILES);
150	    spawnSlots.forEach((slot, index) => {
151	      const next = spawnSlots[(index + 1) % spawnSlots.length]!;
152	      const dx = next.tileX - slot.tileX;
153	      const dy = next.tileY - slot.tileY;
154	      expect(dx * dx + dy * dy).toBeGreaterThan(ENGAGEMENT_RANGE_TILES * ENGAGEMENT_RANGE_TILES);
155	    });
156	  });
157	
158	  it("leaves no empty stretch: every navigable tile is within sight of land, a shoal or a dock", () => {
159	    const { largestObstacleDistanceSquared, openSeaShare } = sliceReport();
160	    expect(largestObstacleDistanceSquared).toBeLessThanOrEqual(SIGHT_RADIUS_TILES * SIGHT_RADIUS_TILES);
161	    const distances = obstacleDistancesSquared(seaMap);
162	    seaMap.terrain.forEach((kind, index) => {
163	      if (kind === Terrain.Sea || kind === Terrain.Dock) expect(distances[index]).toBeLessThanOrEqual(SIGHT_RADIUS_TILES * SIGHT_RADIUS_TILES);
164	      else expect(distances[index]).toBe(0);
165	    });
166	    expect(openSeaShare).toBeLessThan(0.95);
167	  });
168	
169	  it("funnels every route between islands through the hub's crossing, where ships in it see each other", () => {
170	    const { hub } = seaMap;
171	    expect(terrainAt(seaMap, hub.tileX, hub.tileY)).toBe(Terrain.Sea);
172	    // Any two tile centres in the disc are within sight of each other.
173	    const disc = seaMap.terrain.flatMap((_, index) => {
174	      const tileX = index % seaMap.widthTiles;
175	      const tileY = (index - tileX) / seaMap.widthTiles;
176	      return inHubDisc(seaMap, tileX, tileY) ? [{ tileX, tileY }] : [];
177	    });
178	    expect(disc.length).toBeGreaterThan(50);
179	    for (const a of disc) for (const b of disc) expect((a.tileX - b.tileX) ** 2 + (a.tileY - b.tileY) ** 2).toBeLessThanOrEqual(SIGHT_RADIUS_TILES ** 2);
180	    // One route per pair of docks on different islands, each passing within the disc.
181	    const { hubApproach } = sliceReport();
182	    const pairs = seaMap.docks.flatMap((a, index) => seaMap.docks.slice(index + 1).filter((b) => b.island !== a.island));
183	    expect(hubApproach).toHaveLength(pairs.length);
184	    for (const route of hubApproach) expect(4 * route.squaredTiles).toBeLessThanOrEqual(SIGHT_RADIUS_TILES ** 2);
185	  });
186	
187	  it("reaches every dock and spawn slot by sea", () => {
188	    const [first] = spawnSlots;
189	    const costs = seaPathCosts(seaMap, first!.tileX, first!.tileY);
190	    for (const point of [...seaMap.docks, ...spawnSlots]) {
191	      expect(costs[point.tileY * seaMap.widthTiles + point.tileX]).toBeLessThan(Number.MAX_SAFE_INTEGER);
192	    }
193	  });
194	
195	  it("derives its path costs from the map's sub-units per tile", () => {
196	    expect(octileStepCosts(256)).toEqual({ straight: 256, diagonal: 362 });
197	    expect(octileStepCosts(128)).toEqual({ straight: 128, diagonal: 181 });
198	    expect(octileStepCosts(100)).toEqual({ straight: 100, diagonal: 141 });
199	    expect(octileStepCosts(16)).toEqual({ straight: 16, diagonal: 23 });
200	    // The same sea at half the scale costs exactly half as much everywhere, so its costs follow the map, not a constant.
201	    const [first] = spawnSlots;
202	    const full = seaPathCosts(seaMap, first!.tileX, first!.tileY);
203	    const half = seaPathCosts({ ...seaMap, subUnitsPerTile: seaMap.subUnitsPerTile / 2 }, first!.tileX, first!.tileY);
204	    const reachable = full.filter((cost) => cost < Number.MAX_SAFE_INTEGER);
205	    expect(reachable.length).toBeGreaterThan(1000);
206	    expect(half.map((cost) => (cost < Number.MAX_SAFE_INTEGER ? cost * 2 : cost))).toEqual(full);
207	  });
208	});
209	
210	describe("map validators fail on a broken map", () => {
211	  const palm = seaMap.islands[0]!;
212	  const palmDocks = seaMap.docks.filter((dock) => dock.island === 0);
213	
214	  it("a sea larger than 112 × 112 tiles", () => {
215	    expect(MAX_SEA_SIDE_TILES).toBe(112);
216	    expect(Math.max(seaMap.widthTiles, seaMap.heightTiles)).toBeLessThanOrEqual(MAX_SEA_SIDE_TILES);
217	    // Open sea added along the east edge: 112 tiles wide is still compact, 113 is not.
218	    const widened = (widthTiles: number) => ({
219	      ...sliceSeaSource,
220	      widthTiles,
221	      rows: sliceSeaSource.rows.map((row) => row.padEnd(widthTiles, ".")),
222	    });
223	    const tooLarge = `113 × ${seaMap.heightTiles} tiles is larger than 112 × 112`;
224	    expect(issuesFor(widened(113))).toContain(tooLarge);
225	    expect(issuesFor(widened(112)).some((issue) => /larger than 112 × 112/.test(issue))).toBe(false);
226	    const tall = { ...sliceSeaSource, heightTiles: 113, rows: [...sliceSeaSource.rows, ".".repeat(seaMap.widthTiles), ".".repeat(seaMap.widthTiles)] };
227	    expect(issuesFor(tall)).toContain(`${seaMap.widthTiles} × 113 tiles is larger than 112 × 112`);
228	  });
229	
230	  it("an island without a dock", () => {
231	    const edits = Object.fromEntries(palmDocks.map((dock) => [`${dock.tileX},${dock.tileY}`, "."]));
232	    expect(issuesFor(editedMap(edits))).toContain(`${palm.name}: no dock`);
233	  });
234	
235	  it("a dock away from its island's land", () => {
236	    const dock = palmDocks[0]!;
237	    const island = seaMap.islands[0]!;
238	    // A dock tile in the island rectangle's corner, which touches only sea.
239	    const corner = `${island.tileX + island.widthTiles - 1},${island.tileY + island.heightTiles - 1}`;
240	    expect(issuesFor(editedMap({ [corner]: "D", [`${dock.tileX},${dock.tileY}`]: "D" }))).toEqual([
241	      expect.stringMatching(/not beside Palm Key's land/),
242	    ]);
243	  });
244	
245	  it("a fifth island, or land outside every island", () => {
246	    // In the open water of the hub's crossing.
247	    const [tileX, tileY] = [seaMap.hub.tileX - 1, seaMap.hub.tileY - 1];
248	    const extra = { name: "Extra Isle", theme: "mist" as const, tileX, tileY, widthTiles: 3, heightTiles: 3 };
249	    const withFifth = editedMap({ ...fill(tileX, tileY, 2, 2, "#"), [`${tileX + 2},${tileY + 1}`]: "D" }, { islands: [...sliceSeaSource.islands, extra] });
250	    expect(issuesFor(withFifth)).toContain("5 islands, not 4");
251	    expect(issuesFor(editedMap(fill(tileX, tileY, 2, 2, "#")))).toEqual(
252	      expect.arrayContaining([expect.stringMatching(new RegExp(`^land at ${tileX},${tileY} lies in 0 island rectangles`))]),
253	    );
254	  });
255	
256	  it("a large island", () => {
257	    const islands = sliceSeaSource.islands.map((island, index) => (index === 0 ? { ...island, widthTiles: 20 } : island));
258	    expect(issuesFor({ ...sliceSeaSource, islands })).toEqual(expect.arrayContaining([expect.stringMatching(/not a small island/)]));
259	  });
260	
261	  it("no shoals", () => {
262	    const rows = sliceSeaSource.rows.map((row) => row.replaceAll("%", "."));
263	    expect(issuesFor({ ...sliceSeaSource, rows })).toContain("no shoals");
264	  });
265	
266	  it("a dock walled in by shoals", () => {
267	    const dock = palmDocks.find((each) => each.side === "S")!;
268	    // A shoal ring two tiles out, from land edge to land edge.
269	    const ring = {
270	      ...fill(dock.tileX - 3, dock.tileY + 2, 7, 1, "%"),
271	      ...fill(dock.tileX - 3, dock.tileY - 1, 1, 3, "%"),
272	      ...fill(dock.tileX + 3, dock.tileY - 1, 1, 3, "%"),
273	    };
274	    const otherDocks = Object.fromEntries(palmDocks.filter((each) => each !== dock).map((each) => [`${each.tileX},${each.tileY}`, "."]));
275	    const issues = issuesFor(editedMap({ ...ring, ...otherDocks }));
276	    expect(issues).toEqual([expect.stringMatching(/Palm Key S dock at \d+,\d+: not reachable by sea/)]);
277	  });
278	
279	  it("a sea cut in two", () => {
280	    // A shoal row just south of the hub, from edge to edge.
281	    const issues = issuesFor(editedMap(fill(0, seaMap.hub.tileY + 1, sliceSeaSource.widthTiles, 1, "%")));
282	    expect(issues.some((issue) => /not reachable by sea/.test(issue))).toBe(true);
283	  });
284	
285	  it("an empty stretch of sea: open water farther than the sight radius from land, shoals and docks", () => {
286	    // Clear the shoals near the north-west corner: the corner is then out of sight of every obstacle. The map edge does
287	    // not count as one.
288	    const near = 12;
289	    const edits: Record<string, string> = {};
290	    for (let tileY = 0; tileY <= near; tileY++) {
291	      for (let tileX = 0; tileX <= near; tileX++) if (terrainAt(seaMap, tileX, tileY) === Terrain.Shoal) edits[`${tileX},${tileY}`] = ".";
292	    }
293	    expect(Object.keys(edits).length).toBeGreaterThan(0);
294	    const cleared = createSeaMap(editedMap(edits));
295	    expect(obstacleDistancesSquared(cleared)[0]).toBeGreaterThan(SIGHT_RADIUS_TILES * SIGHT_RADIUS_TILES);
296	    expect(issuesFor(editedMap(edits))).toEqual([expect.stringMatching(/^\d+ sea tiles lie farther than 10 tiles from any land, shoal or dock, such as \d+,\d+$/)]);
297	  });
298	
299	  it("a route between islands that avoids the hub", () => {
300	    // A gap in the wall north of the hub, outside its disc: ships crossing between the northern islands no longer meet
301	    // there.
302	    const { hub } = seaMap;
303	    const gap = [hub.tileY - 2 * SIGHT_RADIUS_TILES, hub.tileY - 2 * SIGHT_RADIUS_TILES + 1].map((tileY) => `${hub.tileX},${tileY}`);
304	    for (const tile of gap) {
305	      const [tileX, tileY] = tile.split(",").map(Number);
306	      expect(terrainAt(seaMap, tileX!, tileY!)).toBe(Terrain.Shoal);
307	      expect(inHubDisc(seaMap, tileX!, tileY!)).toBe(false);
308	    }
309	    const issues = issuesFor(editedMap(Object.fromEntries(gap.map((tile) => [tile, "."]))));
310	    expect(issues.length).toBeGreaterThan(0);
311	    for (const issue of issues) expect(issue).toMatch(/^(Palm Key|Ember Rock) \w dock to (Palm Key|Ember Rock) \w dock: a shortest route avoids the hub at \d+,\d+$/);
312	  });
313	
314	  it("a hub off the open sea or away from the centre", () => {
315	    const island = seaMap.islands[0]!;
316	    const onLand = { tileX: island.tileX + 5, tileY: island.tileY + 4 };
317	    expect(terrainAt(seaMap, onLand.tileX, onLand.tileY)).toBe(Terrain.Land);
318	    expect(issuesFor({ ...sliceSeaSource, hub: onLand })).toEqual([`the hub at ${onLand.tileX},${onLand.tileY} is not on open sea`]);
319	    const [slot] = sliceSeaSource.spawnSlots;
320	    expect(issuesFor({ ...sliceSeaSource, hub: { tileX: slot!.tileX, tileY: slot!.tileY } })).toEqual([
321	      `the hub at ${slot!.tileX},${slot!.tileY} is not near the map's centre`,
322	    ]);
323	  });
324	
325	  it("spawn slots in engagement range, on land, inside the archipelago or missing", () => {
326	    const moved = (index: number, tileX: number, tileY: number) =>
327	      editedMap({}, { spawnSlots: sliceSeaSource.spawnSlots.map((slot, each) => (each === index ? { ...slot, tileX, tileY } : slot)) });
